using TMPro;
using UnityEngine;

namespace VentsAndVending.UI
{
    /// <summary>
    /// "Ink &amp; Hazard" UI theme (Docs/Design/ArtStyleGuide.md §UI): fonts and the rounded, ink-outlined sprites every
    /// code-built screen uses. Lives in Resources so runtime UI can find it; generated by UiThemeBuilder (editor).
    /// </summary>
    [CreateAssetMenu(menuName = "Vents & Vending/UI Theme", fileName = "UiTheme")]
    public sealed class UiTheme : ScriptableObject
    {
        public const string ResourcePath = "VentsAndVending/UiTheme";

        [Header("Fonts")]
        public TMP_FontAsset Body;
        public TMP_FontAsset Bold;
        public TMP_FontAsset Display;
        public TMP_FontAsset Mono;

        [Header("Sprites (9-sliced, white fill so Image.color tints them; outlines stay ink-black)")]
        [Tooltip("Rounded rect, 16 px radius, 2 px black outline.")]
        public Sprite Panel;
        [Tooltip("Rounded rect, 16 px radius, no outline (rows, fills).")]
        public Sprite PanelFill;
        [Tooltip("Pill with 2 px black outline (chips, bars).")]
        public Sprite Pill;
        [Tooltip("Pill, no outline (bar fills).")]
        public Sprite PillFill;
        public Sprite Circle;

        private static UiTheme _current;
        private static bool _looked;

        /// <summary>The theme, or null if it hasn't been generated (UI then falls back to flat rectangles).</summary>
        public static UiTheme Current
        {
            get
            {
                if (!_looked)
                {
                    _looked = true;
                    _current = Resources.Load<UiTheme>(ResourcePath);
                }
                return _current;
            }
        }
    }
}
